using TuoiTho.Core.Policy;
using TuoiTho.Parent;
var profile=Environment.GetEnvironmentVariable("M1_PROFILE_ID")??"m1-child";var session=int.TryParse(Environment.GetEnvironmentVariable("M1_SESSION_ID"),out var parsed)?parsed:System.Diagnostics.Process.GetCurrentProcess().SessionId;var client=new LocalParentControlClient();Console.WriteLine($"TuoiTho M1 Parent CLI — profile {profile}, session {session}");while(true){Console.WriteLine("1 +15  2 +30  3 +60  4 custom  5 Override  6 Clear override  7 Parent lock  8 Clear lock  9 Status  0 Exit");Console.Write("> ");var choice=Console.ReadLine();if(choice=="0")break;ParentControlCommand? command=choice switch{"1"=>new(ParentControlAction.GrantMinutes,profile,session,15),"2"=>new(ParentControlAction.GrantMinutes,profile,session,30),"3"=>new(ParentControlAction.GrantMinutes,profile,session,60),"5"=>new(ParentControlAction.EmergencyOverride,profile,session),"6"=>new(ParentControlAction.ClearOverride,profile,session),"7"=>new(ParentControlAction.SetParentLock,profile,session),"8"=>new(ParentControlAction.ClearParentLock,profile,session),"9"=>new(ParentControlAction.GetStatus,profile,session),_=>null};if(choice=="4"){Console.Write("Minutes: ");command=int.TryParse(Console.ReadLine(),out var mins)?new(ParentControlAction.GrantMinutes,profile,session,mins):null;}if(command is null){Console.WriteLine("REJECTED: invalid menu choice.");continue;}try{var result=await client.SendAsync(command);if(!result.Accepted){Console.WriteLine($"REJECTED: {result.Error}");continue;}Console.WriteLine("SUCCESS");if(result.Status is { } s)Console.WriteLine($"Profile={s.ProfileId}; Session={s.ManagedSessionId}; TestMode={s.TestMode}; Used={s.UsedMinutes}; Quota={s.QuotaMinutes}; Grants={s.GrantMinutes}; Remaining={s.RemainingMinutes}; {s.State}");}catch(Exception e)when(e is IOException or UnauthorizedAccessException or OperationCanceledException){Console.WriteLine("REJECTED: local Service unavailable or caller unauthorized.");}}